def run_batch(funcs):
    """Call every function in order and keep going after failures.
    All succeeded -> return the list of results.
    Any failed    -> raise ExceptionGroup("batch failed", errors) after trying them all."""
    pass

def ok():
    return 1

def bad_value():
    raise ValueError("v1")

def bad_key():
    raise KeyError("k1")

def bad_value2():
    raise ValueError("v2")

try:
    run_batch([ok, bad_value, bad_key, bad_value2])
except* ValueError as eg:
    print("ValueError:", len(eg.exceptions))
except* KeyError as eg:
    print("KeyError:", len(eg.exceptions))

practice_challenges.test_code:
def _boom(exc):
    def f():
        raise exc
    return f

assert run_batch([lambda: 1, lambda: 2]) == [1, 2], "all succeed -> return the results in order"
assert run_batch([]) == [], "no functions -> empty list"
try:
    run_batch([_boom(ValueError("a")), lambda: 5, _boom(KeyError("b")), _boom(ValueError("c"))])
except ExceptionGroup as g:
    assert g.message == "batch failed", "use the message 'batch failed'"
    assert [type(e) for e in g.exceptions] == [ValueError, KeyError, ValueError], "keep every error, in call order"
else:
    raise AssertionError("run_batch must raise an ExceptionGroup when something fails")

uth_example:
def check(n):
    if n % 3 == 0:
        raise ValueError(f"bad {n}")
    if n % 5 == 0:
        raise TypeError(f"odd {n}")
    return n

errors = []
for n in [1, 3, 5, 6, 7]:
    try:
        check(n)
    except Exception as e:
        errors.append(e)

try:
    raise ExceptionGroup("batch", errors)
except* ValueError as eg:
    print("value:", [str(e) for e in eg.exceptions])
except* TypeError as eg:
    print("type:", [str(e) for e in eg.exceptions])

